class RunningMean:
    def __init__(self):
        self.total, self.count = 0.0, 0
    def update(self, value):
        self.total += value
        self.count += 1
    def value(self):
        if self.count == 0:
            raise ValueError("Mean is undefined before any updates")
        return self.total / self.count
